//! The protocol's Rust types, generated by typify from the manifest's schemas and annotated as UniFFI records and
//! enums.

use proc_macro2::TokenStream;
use quote::quote;
use serde_json::{Map, Value};
use typify::{TypeSpace, TypeSpaceSettings};

use crate::manifest::{Manifest, Schema};

pub struct Types {
    pub tokens: TokenStream,
    /// Each event's payload type, in the manifest's order.
    pub payloads: Vec<TokenStream>,
    /// Each command's input, output and error types, in the manifest's order.
    pub commands: Vec<[TokenStream; 3]>,
}

pub fn generate(manifest: &Manifest) -> Result<Types, String> {
    let mut schemas = Schemas::default();
    schemas.add(&manifest.descriptor, false)?;
    let payloads = manifest
        .events
        .iter()
        .map(|event| schemas.add(&event.payload, false))
        .collect::<Result<Vec<_>, _>>()?;
    let commands = manifest
        .commands
        .iter()
        .map(|command| {
            Ok([
                schemas.add(&command.input, false)?,
                schemas.add(&command.output, false)?,
                schemas.add(&command.error, true)?,
            ])
        })
        .collect::<Result<Vec<_>, String>>()?;

    let (tokens, idents) = schemas.generate()?;
    Ok(Types {
        tokens,
        payloads: payloads.iter().map(|&i| idents[i].clone()).collect(),
        commands: commands
            .iter()
            .map(|command| command.map(|i| idents[i].clone()))
            .collect(),
    })
}

/// The schemas to generate, with the `$defs` they share.
#[derive(Default)]
struct Schemas {
    defs: Map<String, Value>,
    roots: Vec<(Option<String>, Value)>,
}

impl Schemas {
    /// Adds `schema` and returns its index. `enum_from_const` keeps a single `const` value its own type.
    fn add(&mut self, schema: &Schema, enum_from_const: bool) -> Result<usize, String> {
        let mut root = schema.schema.clone();
        simplify(&mut root);

        if enum_from_const
            && let Some(value) = root.as_object_mut().and_then(|root| root.remove("const"))
        {
            root["enum"] = Value::Array(vec![value]);
        }

        if let Some(Value::Object(defs)) =
            root.as_object_mut().and_then(|root| root.remove("$defs"))
        {
            for (def, definition) in defs {
                // All definitions share one namespace of Rust types.
                match self.defs.get(&def) {
                    Some(existing) if *existing != definition => {
                        return Err(format!(
                            "$defs.{def} is defined differently by two channels"
                        ));
                    }
                    _ => self.defs.insert(def, definition),
                };
            }
        }

        self.roots.push((schema.name.clone(), root));
        Ok(self.roots.len() - 1)
    }

    /// The generated types, and the Rust type of each root by index.
    fn generate(&self) -> Result<(TokenStream, Vec<TokenStream>), String> {
        let mut settings = TypeSpaceSettings::default();
        settings.with_struct_builder(false);
        let mut space = TypeSpace::new(&settings);

        let defs = self
            .defs
            .iter()
            .map(|(name, schema)| {
                Ok((
                    name.clone(),
                    serde_json::from_value(schema.clone()).map_err(|e| e.to_string())?,
                ))
            })
            .collect::<Result<Vec<_>, String>>()?;
        space.add_ref_types(defs).map_err(|e| e.to_string())?;

        let mut idents = Vec::new();
        for (name, schema) in &self.roots {
            let schema: schemars::schema::Schema =
                serde_json::from_value(schema.clone()).map_err(|e| e.to_string())?;
            let id = match name {
                Some(name) => space.add_type_with_name(&schema, Some(name.clone())),
                None => space.add_type(&schema),
            }
            .map_err(|e| e.to_string())?;
            idents.push(space.get_type(&id).map_err(|e| e.to_string())?.ident());
        }

        let mut file: syn::File = syn::parse2(space.to_stream()).map_err(|e| e.to_string())?;
        for item in &mut file.items {
            match item {
                syn::Item::Struct(item) => item
                    .attrs
                    .push(syn::parse_quote!(#[derive(::uniffi::Record)])),
                syn::Item::Enum(item) => item
                    .attrs
                    .push(syn::parse_quote!(#[derive(::uniffi::Enum)])),
                _ => {}
            }
        }

        Ok((quote!(#file), idents))
    }
}

/// Strips what typify would turn into validating newtypes or required defaults; Simlink validates
/// and fills these in.
fn simplify(schema: &mut Value) {
    match schema {
        Value::Object(map) => {
            if let Some(Value::Object(properties)) = map.get_mut("properties") {
                properties.retain(|_, property| {
                    !(property.get("const").is_some() && property.get("default").is_some())
                });
                let kept: Vec<String> = properties.keys().cloned().collect();
                if let Some(Value::Array(required)) = map.get_mut("required") {
                    required.retain(|name| {
                        name.as_str()
                            .is_some_and(|name| kept.iter().any(|kept| kept == name))
                    });
                }
            }
            for key in [
                "minLength",
                "maxLength",
                "pattern",
                "format",
                "default",
                "$schema",
            ] {
                map.remove(key);
            }
            for (key, value) in map.iter_mut() {
                match (key.as_str(), value) {
                    // Keys here are property and definition names, never keywords to strip.
                    ("properties" | "$defs" | "patternProperties", Value::Object(schemas)) => {
                        schemas.values_mut().for_each(simplify)
                    }
                    (_, value) => simplify(value),
                }
            }
        }
        Value::Array(items) => items.iter_mut().for_each(simplify),
        _ => {}
    }
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    #[test]
    fn simplify_strips_keywords_but_keeps_properties_named_like_them() {
        let mut schema = json!({
            "type": "object",
            "properties": {
                "format": { "type": "string", "format": "date-time" },
                "pattern": { "type": "string", "pattern": "^a$", "maxLength": 4 },
                "kind": { "type": "string", "const": "standard", "default": "standard" },
            },
            "required": ["format", "kind"],
            "$defs": { "default": { "type": "string", "minLength": 1 } },
        });
        simplify(&mut schema);

        assert_eq!(
            schema,
            json!({
                "type": "object",
                "properties": { "format": { "type": "string" }, "pattern": { "type": "string" } },
                "required": ["format"],
                "$defs": { "default": { "type": "string" } },
            })
        );
    }
}
